```go
func TestState_NormalizeAfterLoad_JSONRoundTrip(t *testing.T) {
	t.Run("migrates_old_condensed_transcript_lines_from_JSON", func(t *testing.T) {
		// JSON with old field name only (no checkpoint_transcript_start)
		jsonData := []byte(`{
			"session_id": "test-session",
			"condensed_transcript_lines": 42,
			"checkpoint_count": 5
		}`)

		var state State
		err := json.Unmarshal(jsonData, &state)
		require.NoError(t, err)

		state.NormalizeAfterLoad()

		assert.Equal(t, 42, state.CheckpointTranscriptStart)
		assert.Equal(t, 0, state.CondensedTranscriptLines) // cleared
		assert.Equal(t, 5, state.StepCount) // mapped from checkpoint_count JSON tag
		assert.Equal(t, "test-session", state.SessionID)
	})

	t.Run("preserves_new_field_over_old_from_JSON", func(t *testing.T) {
		// JSON with both old and new fields (new field wins)
		jsonData := []byte(`{
			"session_id": "test-session",
			"condensed_transcript_lines": 10,
			"checkpoint_transcript_start": 50
		}`)

		var state State
		err := json.Unmarshal(jsonData, &state)
		require.NoError(t, err)

		state.NormalizeAfterLoad()

		assert.Equal(t, 50, state.CheckpointTranscriptStart) // new field preserved
		assert.Equal(t, 0, state.CondensedTranscriptLines)   // old field cleared
	})

	t.Run("handles_clean_new_format_JSON", func(t *testing.T) {
		// JSON with only new fields (written by new code)
		jsonData := []byte(`{
			"session_id": "test-session",
