		}`)

		var state State
		err := json.Unmarshal(jsonData, &state)
		require.NoError(t, err)

		state.NormalizeAfterLoad()

		assert.Equal(t, 25, state.CheckpointTranscriptStart)
		assert.Equal(t, 3, state.StepCount)
		assert.Equal(t, 0, state.CondensedTranscriptLines)
		assert.Equal(t, 0, state.TranscriptLinesAtStart)
	})
}
